// The vocabulary of what a country can be living through, in its own module so
// that both the campaign shape (state-campaign.ts) and the weekly rule
// (conditions.ts) can name it without either importing the other.
//
// Two families, one mechanic. A condition has always been the right shape for
// "a state the country is inside for weeks at a time": it opens, it worsens or
// eases on its own, it bills a cost every week it runs, it stamps a flag
// authored content gates on, and it raises the draw weight of matching content.
// All of that machinery served weather and nothing else, so the economy was a
// set of instantaneous scalars nothing converted into a state a president has
// to govern through.
/** Struck from outside. Onset reads the nation's authored `geo.disasterExposure`. */
export const ACUTE_CONDITIONS = [
    "earthquake",
    "flood",
    "drought",
    "cyclone",
    "wildfire",
    "pandemic",
    // The three the United States declares against most often and the first six
    // could not name. Severe storm and tornado together are the largest category
    // in the federal declaration record, and winter storms, snowstorms and ice
    // storms are the fourth; heat is the one hazard here the record barely names,
    // because heat is answered by states and utilities rather than declared.
    "tornado",
    "winter-storm",
    "heat-wave",
];
/**
 * Generated by the country's own condition. Onset reads its statistics, and —
 * unlike weather — it closes when the thing that caused it recovers rather than
 * when a timer runs out. A recession that times out while growth is still
 * negative teaches a player that governing is optional.
 */
export const STANDING_CONDITIONS = [
    "unrest",
    "recession",
    "inflation-shock",
    "unemployment-shock",
    "fiscal-crisis",
    "energy-shortage",
    "housing-crunch",
];
export const CONDITION_KINDS = [...ACUTE_CONDITIONS, ...STANDING_CONDITIONS];
const _acuteMatchesWorld = true;
void _acuteMatchesWorld;
const STANDING = new Set(STANDING_CONDITIONS);
/**
 * Which family a kind belongs to.
 *
 * Derived from the kind rather than stored on the record, which is why this
 * whole change needs no save migration: a `NationCondition` written before
 * standing conditions existed answers this question correctly today, because
 * the answer was never a fact about the record.
 */
export function conditionFamily(kind) {
    return STANDING.has(kind) ? "standing" : "acute";
}
export function isStandingCondition(kind) {
    return STANDING.has(kind);
}
/**
 * The acute kinds that are one bad afternoon rather than a state the country is
 * inside for weeks.
 *
 * A tornado touches down, the damage is the damage, and next week is not a
 * worsening of it; a heat wave breaks when the front moves through. Both are
 * over by the time the next tick runs, which is what `lifetime: "incident"`
 * records on the stored condition. A winter storm is deliberately not here: a
 * region stopped for a week has a week of digging out behind it, and that is
 * the shape the weekly rule is written for.
 *
 * Kept as a list over `AcuteCondition` rather than a third family, because an
 * incident is the same record, the same store and the same id scheme — only its
 * lifetime differs.
 */
export const INCIDENT_KINDS = ["tornado", "heat-wave"];
const INCIDENTS = new Set(INCIDENT_KINDS);
export function isIncidentKind(kind) {
    return INCIDENTS.has(kind);
}
